import { test, expect } from '@playwright/test';

test.describe('Form Submission Errors', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-page');
  });

  test('should display error message when form is submitted with empty fields', async ({ page }) => {
    await page.getByRole('button', { name: /submit/i }).click();
    const errorMessage = await page.getByText(/this field is required/i);
    await expect(errorMessage).toBeVisible();
    await errorMessage.scrollIntoViewIfNeeded();
    await expect(page).toHaveURL(/form-page/);
  });

  test('should scroll to error message when invalid email is submitted', async ({ page }) => {
    await page.getByLabel('Email').fill('invalid-email');
    await page.getByRole('button', { name: /submit/i }).click();
    const errorMessage = await page.getByText(/please enter a valid email/i);
    await expect(errorMessage).toBeVisible();
    await errorMessage.scrollIntoViewIfNeeded();
    await expect(page).toHaveURL(/form-page/);
  });
});
